/**
 * Ilustrações dos exercícios — GERADO por scripts/baixar-ilustracoes.py.
 * Não editar à mão: edite o MAPA do script e rode de novo.
 *
 * Fonte: yuhonas/free-exercise-db (Unlicense, domínio público). Duas fotos
 * por exercício — início e fim do movimento. A UI alterna as duas.
 *
 * `aprox` = mesmo movimento, aparelho diferente. A UI rotula.
 * `instrucoes` vêm da base, em INGLÊS — não foram traduzidas.
 *
 * `musculos`, `equipamento`, `forca` e `mecanica` alimentam a sugestão
 * de substituto (lib/treino/substituir.ts). ATENÇÃO: quando `aprox` é
 * true, o `equipamento` é o do exercício da BASE, não o seu — por isso
 * o nome do seu exercício manda na hora de decidir o aparelho.
 */

export interface Ilustracao {
  /** Pasta em public/ex/ com 0.webp (início) e 1.webp (fim). */
  pasta: string;
  /** Movimento igual, aparelho diferente — a UI avisa. */
  aprox: boolean;
  /** Nome na base de origem, pra rastrear de onde veio. */
  fonte: string;
  instrucoes: string[];
  /** Músculo(s) principal(is) — em inglês, como vem da base. */
  musculos: string[];
  secundarios: string[];
  /** Não confie quando `aprox` for true — ver cabeçalho. */
  equipamento: string | null;
  /** push | pull | static */
  forca: string | null;
  /** compound | isolation */
  mecanica: string | null;
}

/** Chave = `nome_busca` (ver lib/treino/texto.ts). */
export const ILUSTRACOES: Record<string, Ilustracao> = {
  "abdominal (maquina)": { pasta: "Ab_Crunch_Machine", aprox: false, fonte: "Ab Crunch Machine", musculos: ["abdominals"], secundarios: [], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.", "At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.", "After a second pause, slowly return to the starting position as you breathe in.", "Repeat the movement for the prescribed amount of repetitions."] },
  "abdominal declinado": { pasta: "Decline_Crunch", aprox: false, fonte: "Decline Crunch", musculos: ["abdominals"], secundarios: [], equipamento: "body only", forca: "pull", mecanica: "isolation", instrucoes: ["Secure your legs at the end of the decline bench and lie down.", "Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.", "While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.", "Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.", "After the one second contraction, begin to come down slowly again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."] },
  "agachamento (barra)": { pasta: "Barbell_Full_Squat", aprox: false, fonte: "Barbell Full Squat", musculos: ["quadriceps"], secundarios: ["calves", "glutes", "hamstrings", "lower back"], equipamento: "barbell", forca: "push", mecanica: "compound", instrucoes: ["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.", "Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.", "Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "agachamento (smith)": { pasta: "Smith_Machine_Squat", aprox: false, fonte: "Smith Machine Squat", musculos: ["quadriceps"], secundarios: ["calves", "glutes", "hamstrings", "lower back"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "cadeira abdutora (maquina)": { pasta: "Thigh_Abductor", aprox: false, fonte: "Thigh Abductor", musculos: ["abductors"], secundarios: ["glutes"], equipamento: "machine", forca: "push", mecanica: "isolation", instrucoes: ["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them away from each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."] },
  "cadeira adutora (maquina)": { pasta: "Thigh_Adductor", aprox: false, fonte: "Thigh Adductor", musculos: ["adductors"], secundarios: ["glutes", "hamstrings"], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them towards each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."] },
  "cadeira extensora (maquina)": { pasta: "Leg_Extensions", aprox: false, fonte: "Leg Extensions", musculos: ["quadriceps"], secundarios: [], equipamento: "machine", forca: "push", mecanica: "isolation", instrucoes: ["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.", "Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.", "Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.", "Repeat for the recommended amount of times."] },
  "cadeira flexora (maquina)": { pasta: "Seated_Leg_Curl", aprox: false, fonte: "Seated Leg Curl", musculos: ["hamstrings"], secundarios: [], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.", "Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.", "As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."] },
  "crossover na polia": { pasta: "Cable_Crossover", aprox: false, fonte: "Cable Crossover", musculos: ["chest"], secundarios: ["shoulders"], equipamento: "cable", forca: "push", mecanica: "isolation", instrucoes: ["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.", "Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."] },
  "crucifixo (maquina)": { pasta: "Butterfly", aprox: false, fonte: "Butterfly", musculos: ["chest"], secundarios: [], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["Sit on the machine with your back flat on the pad.", "Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.", "Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.", "Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.", "Repeat for the recommended amount of repetitions."] },
  "crucifixo invertido (maquina)": { pasta: "Reverse_Machine_Flyes", aprox: false, fonte: "Reverse Machine Flyes", musculos: ["shoulders"], secundarios: [], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.", "In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.", "Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.", "Pause at the rear of the movement, and slowly return the weight to the starting position."] },
  "desenvolvimento (halter)": { pasta: "Dumbbell_Shoulder_Press", aprox: false, fonte: "Dumbbell Shoulder Press", musculos: ["shoulders"], secundarios: ["triceps"], equipamento: "dumbbell", forca: "push", mecanica: "compound", instrucoes: ["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.", "Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.", "Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.", "Now, exhale and push the dumbbells upward until they touch at the top.", "Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."] },
  "desenvolvimento maquina": { pasta: "Machine_Shoulder_Military_Press", aprox: false, fonte: "Machine Shoulder (Military) Press", musculos: ["shoulders"], secundarios: ["triceps"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["Sit down on the Shoulder Press Machine and select the weight.", "Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.", "Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.", "Lower the handles slowly back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."] },
  "desenvolvimento militar (barra)": { pasta: "Standing_Military_Press", aprox: false, fonte: "Standing Military Press", musculos: ["shoulders"], secundarios: ["triceps"], equipamento: "barbell", forca: "push", mecanica: "compound", instrucoes: ["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.", "Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.", "Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "Lower the bar down to the collarbone slowly as you inhale.", "Lift the bar back up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."] },
  "elevacao frontal (halter)": { pasta: "Front_Dumbbell_Raise", aprox: false, fonte: "Front Dumbbell Raise", musculos: ["shoulders"], secundarios: [], equipamento: "dumbbell", forca: "push", mecanica: "isolation", instrucoes: ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.", "While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.", "Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.", "Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."] },
  "elevacao lateral (halter)": { pasta: "Side_Lateral_Raise", aprox: false, fonte: "Side Lateral Raise", musculos: ["shoulders"], secundarios: [], equipamento: "dumbbell", forca: "push", mecanica: "isolation", instrucoes: ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.", "While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbells back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."] },
  "elevacao lateral unilateral (cabo)": { pasta: "One-Arm_Side_Laterals", aprox: true, fonte: "One-Arm Side Laterals", musculos: ["shoulders"], secundarios: [], equipamento: "dumbbell", forca: "push", mecanica: "isolation", instrucoes: ["Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.", "Stand with a straight torso and have the dumbbell by your side at arm's length with the palm of the hand facing you. This will be your starting position.", "While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbell back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions.", "Switch arms and repeat the exercise."] },
  "elevacao pelvica (barra)": { pasta: "Barbell_Hip_Thrust", aprox: false, fonte: "Barbell Hip Thrust", musculos: ["glutes"], secundarios: ["calves", "hamstrings"], equipamento: "barbell", forca: "push", mecanica: "compound", instrucoes: ["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."] },
  "extensao de panturrilha (maquina)": { pasta: "Calf_Press", aprox: false, fonte: "Calf Press", musculos: ["calves"], secundarios: [], equipamento: "machine", forca: "push", mecanica: "isolation", instrucoes: ["Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.", "Select an appropriate weight, and grasp the handles. This will be your starting position.", "Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.", "After a brief pause, reverse the motion and repeat."] },
  "extensao lombar (hiperextensao com peso)": { pasta: "Hyperextensions_Back_Extensions", aprox: false, fonte: "Hyperextensions (Back Extensions)", musculos: ["lower back"], secundarios: ["glutes", "hamstrings"], equipamento: "other", forca: "pull", mecanica: "isolation", instrucoes: ["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.", "Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.", "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.", "Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.", "Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.", "Repeat for the recommended amount of repetitions."] },
  "leg press 45º (maquina)": { pasta: "Leg_Press", aprox: false, fonte: "Leg Press", musculos: ["quadriceps"], secundarios: ["calves", "glutes", "hamstrings"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."] },
  "levantamento terra (barra)": { pasta: "Barbell_Deadlift", aprox: false, fonte: "Barbell Deadlift", musculos: ["lower back"], secundarios: ["calves", "forearms", "glutes", "hamstrings", "lats", "middle back", "quadriceps", "traps"], equipamento: "barbell", forca: "pull", mecanica: "compound", instrucoes: ["Stand in front of a loaded barbell.", "While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.", "While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.", "Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.", "Perform the amount of repetitions prescribed in the program."] },
  "mesa flexora (maquina)": { pasta: "Lying_Leg_Curls", aprox: false, fonte: "Lying Leg Curls", musculos: ["hamstrings"], secundarios: [], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."] },
  "puxada alta (cabo)": { pasta: "Wide-Grip_Lat_Pulldown", aprox: false, fonte: "Wide-Grip Lat Pulldown", musculos: ["lats"], secundarios: ["biceps", "middle back", "shoulders"], equipamento: "cable", forca: "pull", mecanica: "compound", instrucoes: ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."] },
  "puxada alta - pegada fechada (cabo)": { pasta: "Close-Grip_Front_Lat_Pulldown", aprox: false, fonte: "Close-Grip Front Lat Pulldown", musculos: ["lats"], secundarios: ["biceps", "middle back", "shoulders"], equipamento: "cable", forca: "pull", mecanica: "compound", instrucoes: ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.", "After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "6. Repeat this motion for the prescribed amount of repetitions."] },
  "remada baixa triangulo": { pasta: "Seated_Cable_Rows", aprox: false, fonte: "Seated Cable Rows", musculos: ["middle back"], secundarios: ["biceps", "lats", "shoulders"], equipamento: "cable", forca: "pull", mecanica: "compound", instrucoes: ["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."] },
  "remada iso-lateral (maquina)": { pasta: "Leverage_Iso_Row", aprox: false, fonte: "Leverage Iso Row", musculos: ["lats"], secundarios: ["biceps", "middle back"], equipamento: "machine", forca: "pull", mecanica: "compound", instrucoes: ["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."] },
  "remada meadows (barra)": { pasta: "Bent_Over_One-Arm_Long_Bar_Row", aprox: true, fonte: "Bent Over One-Arm Long Bar Row", musculos: ["middle back"], secundarios: ["biceps", "lats", "lower back", "traps"], equipamento: "barbell", forca: "pull", mecanica: "compound", instrucoes: ["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.", "Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.", "Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.", "Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.", "Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).", "Repeat for the recommended amount of repetitions and switch arms."] },
  "remada sentada (maquina)": { pasta: "Leverage_High_Row", aprox: false, fonte: "Leverage High Row", musculos: ["middle back"], secundarios: ["lats"], equipamento: "machine", forca: "pull", mecanica: "compound", instrucoes: ["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position.", "For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."] },
  "remada sentada pegada aberta (cabo)": { pasta: "Seated_Cable_Rows", aprox: false, fonte: "Seated Cable Rows", musculos: ["middle back"], secundarios: ["biceps", "lats", "shoulders"], equipamento: "cable", forca: "pull", mecanica: "compound", instrucoes: ["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."] },
  "remada unilateral (halter)": { pasta: "One-Arm_Dumbbell_Row", aprox: false, fonte: "One-Arm Dumbbell Row", musculos: ["middle back"], secundarios: ["biceps", "lats", "shoulders"], equipamento: "dumbbell", forca: "pull", mecanica: "compound", instrucoes: ["Choose a flat bench and place a dumbbell on each side of it.", "Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.", "Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.", "Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.", "Lower the resistance straight down to the starting position. Breathe in as you perform this step.", "Repeat the movement for the specified amount of repetitions.", "Switch sides and repeat again with the other arm."] },
  "rosca direta (cabo)": { pasta: "Standing_Biceps_Cable_Curl", aprox: false, fonte: "Standing Biceps Cable Curl", musculos: ["biceps"], secundarios: [], equipamento: "cable", forca: "pull", mecanica: "isolation", instrucoes: ["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the curl bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."] },
  "rosca direta (halter)": { pasta: "Dumbbell_Bicep_Curl", aprox: false, fonte: "Dumbbell Bicep Curl", musculos: ["biceps"], secundarios: ["forearms"], equipamento: "dumbbell", forca: "pull", mecanica: "isolation", instrucoes: ["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."] },
  "rosca direta (maquina)": { pasta: "Machine_Bicep_Curl", aprox: false, fonte: "Machine Bicep Curl", musculos: ["biceps"], secundarios: [], equipamento: "machine", forca: "pull", mecanica: "isolation", instrucoes: ["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.", "Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.", "Pause at the top of the movement, and then slowly return the weight to the starting position.", "Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."] },
  "rosca inclinada sentado (halter)": { pasta: "Incline_Dumbbell_Curl", aprox: false, fonte: "Incline Dumbbell Curl", musculos: ["biceps"], secundarios: [], equipamento: "dumbbell", forca: "pull", mecanica: "isolation", instrucoes: ["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.", "While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.", "Slowly begin to bring the dumbbells back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."] },
  "rosca scott (barra)": { pasta: "Preacher_Curl", aprox: false, fonte: "Preacher Curl", musculos: ["biceps"], secundarios: [], equipamento: "barbell", forca: "pull", mecanica: "isolation", instrucoes: ["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.", "With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.", "As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.", "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.", "Repeat for the recommended amount of repetitions."] },
  "stiff (barra)": { pasta: "Stiff-Legged_Barbell_Deadlift", aprox: false, fonte: "Stiff-Legged Barbell Deadlift", musculos: ["hamstrings"], secundarios: ["glutes", "lower back"], equipamento: "barbell", forca: "pull", mecanica: "compound", instrucoes: ["Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.", "Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.", "Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.", "Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.", "Repeat for the recommended amount of repetitions."] },
  "supino articulado deitado": { pasta: "Leverage_Chest_Press", aprox: false, fonte: "Leverage Chest Press", musculos: ["chest"], secundarios: ["shoulders", "triceps"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.", "Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."] },
  "supino inclinado (halter)": { pasta: "Incline_Dumbbell_Press", aprox: false, fonte: "Incline Dumbbell Press", musculos: ["chest"], secundarios: ["shoulders", "triceps"], equipamento: "dumbbell", forca: "push", mecanica: "compound", instrucoes: ["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.", "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.", "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."] },
  "supino inclinado (maquina smith)": { pasta: "Smith_Machine_Incline_Bench_Press", aprox: false, fonte: "Smith Machine Incline Bench Press", musculos: ["chest"], secundarios: ["shoulders", "triceps"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your upper chest.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."] },
  "supino inclinado (maquina)": { pasta: "Leverage_Incline_Chest_Press", aprox: false, fonte: "Leverage Incline Chest Press", musculos: ["chest"], secundarios: ["shoulders", "triceps"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."] },
  "supino reto (barra)": { pasta: "Barbell_Bench_Press_-_Medium_Grip", aprox: false, fonte: "Barbell Bench Press - Medium Grip", musculos: ["chest"], secundarios: ["shoulders", "triceps"], equipamento: "barbell", forca: "push", mecanica: "compound", instrucoes: ["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."] },
  "supino sentado (maquina)": { pasta: "Leverage_Chest_Press", aprox: false, fonte: "Leverage Chest Press", musculos: ["chest"], secundarios: ["shoulders", "triceps"], equipamento: "machine", forca: "push", mecanica: "compound", instrucoes: ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.", "Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."] },
  "triceps corda (polia)": { pasta: "Triceps_Pushdown_-_Rope_Attachment", aprox: false, fonte: "Triceps Pushdown - Rope Attachment", musculos: ["triceps"], secundarios: [], equipamento: "cable", forca: "push", mecanica: "isolation", instrucoes: ["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.", "Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."] },
  "triceps frances (polia)": { pasta: "Cable_Rope_Overhead_Triceps_Extension", aprox: false, fonte: "Cable Rope Overhead Triceps Extension", musculos: ["triceps"], secundarios: [], equipamento: "cable", forca: "push", mecanica: "isolation", instrucoes: ["Attach a rope to the bottom pulley of the pulley machine.", "Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.", "Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out.", "Repeat for the recommended amount of repetitions."] },
  "triceps na polia": { pasta: "Triceps_Pushdown", aprox: false, fonte: "Triceps Pushdown", musculos: ["triceps"], secundarios: [], equipamento: "cable", forca: "push", mecanica: "isolation", instrucoes: ["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.", "Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."] },
  "triceps testa (halter)": { pasta: "EZ-Bar_Skullcrusher", aprox: true, fonte: "EZ-Bar Skullcrusher", musculos: ["triceps"], secundarios: ["forearms"], equipamento: "e-z curl bar", forca: "push", mecanica: "isolation", instrucoes: ["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.", "Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.", "Lift the bar back to the starting position by extending the elbow and exhaling.", "Repeat."] },
};

export function ilustracaoDe(nomeBusca: string): Ilustracao | null {
  return ILUSTRACOES[nomeBusca] ?? null;
}
